insert into public.qd_books (id,title,author,content) values ('father-son','Әке мен бала','Ыбырай Алтынсарин','{"id":"father-son","title":"Әке мен бала","author":"Ыбырай Алтынсарин","source":"https://adebiportal.kz/ru/news/view/stranicka-ucenika-ybyrai-altynsarin__23580","summary":{"ru":"Отец подбирает старую подкову, которую сын поленился поднять. Продав её, он покупает вишни. Сын много раз наклоняется за ягодами и понимает ценность небольшого труда.","en":"A father picks up an old horseshoe that his son would not bother to lift. He sells it and buys cherries. The son bends down repeatedly to pick up berries and learns the value of small efforts."},"characters":[{"name":"Әке","description":{"ru":"Отец: учит примером.","en":"Father: teaches through his actions."}},{"name":"Бала","description":{"ru":"Сын: учится ценить труд.","en":"Son: learns to value effort."}}],"events":[{"ru":"Отец находит подкову.","en":"The father finds a horseshoe."},{"ru":"Отец продаёт подкову и покупает вишни.","en":"The father sells the horseshoe and buys cherries."},{"ru":"Сын подбирает упавшие вишни.","en":"The son picks up fallen cherries."}],"vocabulary":[{"kk":"таға","translation":{"ru":"подкова","en":"horseshoe"}},{"kk":"еңбек","translation":{"ru":"труд","en":"effort"}},{"kk":"шие","translation":{"ru":"вишня","en":"cherry"}}],"chapters":[{"id":"father-son-summary","title":{"ru":"Краткое содержание","en":"Summary"},"summary":{"ru":"Отец подбирает старую подкову, которую сын поленился поднять. Продав её, он покупает вишни. Сын много раз наклоняется за ягодами и понимает ценность небольшого труда.","en":"A father picks up an old horseshoe that his son would not bother to lift. He sells it and buys cherries. The son bends down repeatedly to pick up berries and learns the value of small efforts."}}],"quiz":{"bookId":"father-son","lessonId":"books-2"}}') on conflict do nothing;
insert into public.qd_book_chapters (id,book_id,title,summary) values ('father-son-summary','father-son','{"ru":"Краткое содержание","en":"Summary"}','{"ru":"Отец подбирает старую подкову, которую сын поленился поднять. Продав её, он покупает вишни. Сын много раз наклоняется за ягодами и понимает ценность небольшого труда.","en":"A father picks up an old horseshoe that his son would not bother to lift. He sells it and buys cherries. The son bends down repeatedly to pick up berries and learns the value of small efforts."}') on conflict do nothing;
insert into public.qd_books (id,title,author,content) values ('precious-herb','Асыл шөп','Ыбырай Алтынсарин','{"id":"precious-herb","title":"Асыл шөп","author":"Ыбырай Алтынсарин","source":"https://adebiportal.kz/ru/news/view/stranicka-ucenika-ybyrai-altynsarin__23580","summary":{"ru":"Зылиха и Батима несут тяжёлые корзины с фруктами. Зылиха жалуется, а Батима спокойно продолжает путь. Её «драгоценная трава» — терпение: оно помогает справляться с трудностями.","en":"Zyliha and Batima carry heavy loads of fruit. Zyliha complains, while Batima keeps going calmly. Her “precious herb” is patience, which helps her face difficulties."},"characters":[{"name":"Зылиха","description":{"ru":"Жалуется на тяжесть ноши.","en":"Complains about the heavy load."}},{"name":"Бәтима","description":{"ru":"Объясняет силу терпения.","en":"Explains the power of patience."}}],"events":[{"ru":"Девушки несут фрукты.","en":"The girls carry fruit."},{"ru":"Зылиха жалуется.","en":"Zyliha complains."},{"ru":"Батима говорит о терпении.","en":"Batima talks about patience."}],"vocabulary":[{"kk":"сабыр","translation":{"ru":"терпение","en":"patience"}},{"kk":"жеміс","translation":{"ru":"фрукт","en":"fruit"}},{"kk":"ауыр","translation":{"ru":"тяжёлый","en":"heavy"}}],"chapters":[{"id":"precious-herb-summary","title":{"ru":"Краткое содержание","en":"Summary"},"summary":{"ru":"Зылиха и Батима несут тяжёлые корзины с фруктами. Зылиха жалуется, а Батима спокойно продолжает путь. Её «драгоценная трава» — терпение: оно помогает справляться с трудностями.","en":"Zyliha and Batima carry heavy loads of fruit. Zyliha complains, while Batima keeps going calmly. Her “precious herb” is patience, which helps her face difficulties."}}],"quiz":{"bookId":"precious-herb","lessonId":"books-4"}}') on conflict do nothing;
insert into public.qd_book_chapters (id,book_id,title,summary) values ('precious-herb-summary','precious-herb','{"ru":"Краткое содержание","en":"Summary"}','{"ru":"Зылиха и Батима несут тяжёлые корзины с фруктами. Зылиха жалуется, а Батима спокойно продолжает путь. Её «драгоценная трава» — терпение: оно помогает справляться с трудностями.","en":"Zyliha and Batima carry heavy loads of fruit. Zyliha complains, while Batima keeps going calmly. Her “precious herb” is patience, which helps her face difficulties."}') on conflict do nothing;
